#!/usr/bin/env node
/**
 * build-bundle: write bin/recap.mjs, the whole CLI and MCP server in ONE file
 * with no dependency. An installed plugin has no node_modules and no build
 * step, so this committed file is what makes `recap` and the MCP server run
 * there, in the .mcpb bundle, and through `npx github:Aboudjem/recap-studio`.
 *
 *   node scripts/build-bundle.mjs          rebuild bin/recap.mjs
 *   node scripts/build-bundle.mjs --check  exit 1 when the committed file is stale
 */
import { readFileSync, writeFileSync, mkdirSync, existsSync, chmodSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { build } from "esbuild";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const out = resolve(root, "bin/recap.mjs");
const example = readFileSync(resolve(root, "fixtures/topics/latest-ai-models.json"), "utf8");
const pkg = (name) => resolve(root, "packages", name, "src/index.ts");

const result = await build({
  entryPoints: [pkg("cli")],
  bundle: true,
  platform: "node",
  format: "esm",
  target: "node20",
  write: false,
  legalComments: "none",
  charset: "utf8",
  // Bundle from source, so the result never depends on a stale dist/.
  alias: {
    "@recap-studio/content-pipeline": pkg("content-pipeline"),
    "@recap-studio/validation": pkg("validation"),
    "@recap-studio/html-renderer": pkg("html-renderer"),
    "@recap-studio/mcp-server": pkg("mcp-server"),
  },
  define: { __RECAP_EXAMPLE__: JSON.stringify(example) },
  banner: {
    js: "// Generated by scripts/build-bundle.mjs. Do not edit: change packages/*/src and rebuild.",
  },
  logLevel: "warning",
});

const code = result.outputFiles[0].text;

if (process.argv.includes("--check")) {
  const current = existsSync(out) ? readFileSync(out, "utf8") : "";
  if (current !== code) {
    console.error("bin/recap.mjs is stale. Run `npm run bundle` and commit the result.");
    process.exit(1);
  }
  console.log("ok: bin/recap.mjs matches the sources");
} else {
  mkdirSync(dirname(out), { recursive: true });
  writeFileSync(out, code, "utf8");
  chmodSync(out, 0o755);
  console.log(`wrote bin/recap.mjs (${(Buffer.byteLength(code) / 1024).toFixed(1)} KB)`);
}
